-- Remove seeded categories. Releases referencing them have category_id set to
-- NULL via ON DELETE SET NULL.
DELETE FROM categories WHERE id IN (
    1000,1010,1020,1030,1040,1050,1080,1090,
    2000,2010,2020,2030,2040,2045,2050,2060,
    3000,3010,3020,3030,3040,
    4000,4010,4020,4030,4040,4050,4060,4070,
    5000,5020,5030,5040,5045,5050,5060,5070,5080,
    6000,6010,6020,6030,6040,6060,
    7000,7010,7020,7030,7040,7060,
    8000,8010
);
